/**
 * Typed MURKA retail layout (murom_world/config: locations.yaml + products.yaml, generated by generate_store.py), in
 * the units of the MURKA code (metres, radians, map frame). The mission logic (FSM states, navigation, manipulation,
 * perception) works on this; the station items (products, Targets, Zones) come from io/webots/retail_layout.ts.
 */
import { parseYaml, YamlValue } from '../../io/webots/yaml';

export interface Pose3 { x: number; y: number; yaw: number }
export type SlotKind = 'gondola' | 'bulk' | 'pallet' | 'packing' | string;
export interface RetailSlot {
  id: string; kind: SlotKind;
  pose: { x: number; y: number; z: number };
  approach?: Pose3; standoff?: Pose3; approachAlt?: Pose3; standoffAlt?: Pose3;
  arm?: string; armAlt?: string; ceiling?: number; depthIn?: number;
}
export interface CatalogEntry { sku: string; size: [number, number, number]; color: [number, number, number]; twoHand: boolean }
export interface BasketSlot { id: string; dx: number; dy: number; dz: number; arm: string }
export interface RetailLayout {
  frame: string;
  targets: Record<string, Pose3>;
  dock: { approach: Pose3; standoff: Pose3; radius: number } | null;
  slots: Record<string, RetailSlot>;
  basket: Record<string, BasketSlot>;
  catalog: Record<string, CatalogEntry>;
  instances: Array<{ name: string; sku: string; slot: string }>;
}

type Obj = { [k: string]: YamlValue };
const num = (v: YamlValue | undefined, d = 0) => (typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : d);
const obj = (v: YamlValue | undefined): Obj => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Obj) : {});
const pose3 = (v: YamlValue | undefined): Pose3 | undefined => { if (!v || typeof v !== 'object') return undefined; const o = obj(v); return { x: num(o.x), y: num(o.y), yaw: num(o.yaw) }; };

/** Parse products.yaml + locations.yaml texts. */
export function parseRetailLayout(productsYaml: string, locationsYaml: string): RetailLayout {
  const prod = obj(parseYaml(productsYaml));
  const loc = obj(parseYaml(locationsYaml));
  const targets: Record<string, Pose3> = {};
  for (const [k, v] of Object.entries(obj(loc.targets))) targets[k] = pose3(v)!;
  const d = obj(loc.dock);
  const dock = d.approach && d.standoff ? { approach: pose3(d.approach)!, standoff: pose3(d.standoff)!, radius: num(d.radius, 0.06) } : null;
  const slots: Record<string, RetailSlot> = {};
  for (const [id, raw] of Object.entries(obj(loc.slots))) {
    const s = obj(raw); const p = obj(s.pose);
    slots[id] = {
      id, kind: String(s.kind ?? 'gondola'), pose: { x: num(p.x), y: num(p.y), z: num(p.z) },
      approach: pose3(s.approach), standoff: pose3(s.standoff), approachAlt: pose3(s.approach_alt), standoffAlt: pose3(s.standoff_alt),
      arm: s.arm !== undefined ? String(s.arm) : undefined, armAlt: s.arm_alt !== undefined ? String(s.arm_alt) : undefined,
      ceiling: s.ceiling !== undefined ? num(s.ceiling) : undefined, depthIn: s.depth_in !== undefined ? num(s.depth_in) : undefined,
    };
  }
  const basket: Record<string, BasketSlot> = {};
  for (const [id, raw] of Object.entries(obj(loc.basket_slots))) { const b = obj(raw); basket[id] = { id, dx: num(b.dx), dy: num(b.dy), dz: num(b.dz), arm: String(b.arm ?? 'left') }; }
  const catalog: Record<string, CatalogEntry> = {};
  for (const [sku, raw] of Object.entries(obj(prod.catalog))) {
    const c = obj(raw);
    const size = (Array.isArray(c.size) ? c.size : [0.1, 0.1, 0.1]).map((v) => num(v)) as [number, number, number];
    const color = (Array.isArray(c.color) ? c.color : [0.7, 0.7, 0.7]).map((v) => num(v)) as [number, number, number];
    catalog[sku] = { sku, size, color, twoHand: c.two_hand === true };
  }
  const instances = (Array.isArray(prod.instances) ? prod.instances : []).map((r) => { const o = obj(r); return { name: String(o.name), sku: String(o.sku), slot: String(o.slot) }; });
  return { frame: String(loc.frame ?? 'map'), targets, dock, slots, basket, catalog, instances };
}

/** Slot ids with a prefix, sorted (orchestrator slots_by_prefix + sorted()). */
export const slotsByPrefix = (L: RetailLayout, prefix: string): string[] => Object.keys(L.slots).filter((s) => s.startsWith(prefix)).sort();
